import { TouchableOpacity, Text } from 'react-native'

export const ResendOTPButton = ({
	handleResendCode
}: {
	handleResendCode: () => void
}) => {
	const { theme } = useTheme()

	return (
		<TouchableOpacity
			style={styles.resendCodeContainer}
			onPress={handleResendCode}
		>
			<Text style={styles.resendCodeText(theme)}>Resend code</Text>
		</TouchableOpacity>
	)
}

const styles = defineStyles({
	resendCodeContainer: {
		position: 'absolute',
		bottom: 0,
		left: 0,
		right: 0,
		paddingVertical: 8,
		alignItems: 'center'
	},
	resendCodeText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[600]
	})
})
